package com.adaptiq.dao;
import com.adaptiq.config.DatabaseConnection; import com.adaptiq.exception.DatabaseException; import com.adaptiq.model.*; import java.sql.*; import java.util.*;
public final class RecommendationDAO { public List<Recommendation> findActive(long student){String q="SELECT r.recommendation_id,r.student_id,r.topic_id,t.topic_name,r.recommendation_text,r.recommended_difficulty,r.status,r.created_at FROM recommendations r JOIN topics t ON t.topic_id=r.topic_id WHERE r.student_id=? AND r.status='ACTIVE' ORDER BY r.created_at DESC";try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,student);try(ResultSet r=s.executeQuery()){List<Recommendation>x=new ArrayList<>();while(r.next()){Recommendation v=new Recommendation();v.setRecommendationId(r.getLong(1));v.setStudentId(r.getLong(2));v.setTopicId(r.getLong(3));v.setTopicName(r.getString(4));v.setRecommendationText(r.getString(5));v.setRecommendedDifficulty(Difficulty.valueOf(r.getString(6)));v.setStatus(r.getString(7));x.add(v);}return x;}}catch(SQLException e){throw new DatabaseException("Could not retrieve recommendations.",e);}} public void replaceActive(long student,List<Recommendation>x){try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement s=c.prepareStatement("UPDATE recommendations SET status='ARCHIVED' WHERE student_id=? AND status='ACTIVE'")){s.setLong(1,student);s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("INSERT INTO recommendations (student_id,topic_id,recommendation_text,recommended_difficulty,recommended_question_count,status) VALUES (?, ?, ?, ?, 10, 'ACTIVE')")){for(Recommendation v:x){s.setLong(1,student);s.setLong(2,v.getTopicId());s.setString(3,v.getRecommendationText());s.setString(4,v.getRecommendedDifficulty().name());s.addBatch();}s.executeBatch();}c.commit();}catch(SQLException e){try{c.rollback();}catch(SQLException ignored){}throw new DatabaseException("Could not refresh recommendations.",e);}}catch(SQLException e){throw new DatabaseException("Could not refresh recommendations.",e);}} public void markCompleted(long id,long student){try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement("UPDATE recommendations SET status='COMPLETED' WHERE recommendation_id=? AND student_id=? AND status='ACTIVE'")){s.setLong(1,id);s.setLong(2,student);if(s.executeUpdate()!=1)throw new DatabaseException("Recommendation is unavailable.");}catch(SQLException e){throw new DatabaseException("Could not complete recommendation.",e);}} }
